SELECT d.entity_kind || ':' || d.entity_name FROM project_documents d WHERE d.project_id = $1 AND d.entity_kind = 'board' AND d.entity_name = 'order' UNION ALL SELECT 'дерево · ' || f.name FROM code_fact f WHERE f.project_id = $1 AND f.kind = 'plan-order' UNION ALL SELECT 'датчик «plan-order» ' || fact_gap($1, 'plan-order') || ': есть ли доска порядка в дереве — не установлено' WHERE NOT fact_fresh($1, 'plan-order') UNION ALL SELECT 'пересборка набора не прошла: доска порядка не установлена' WHERE NOT EXISTS (SELECT 1 FROM reproject_state r WHERE r.project_id = $1 AND r.ok)
